INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Acid', 'acid', 'gear', 2500, 1, 'When you take the Attack action, you can replace one of your attacks with throwing a vial of Acid. Target one creature or object you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 2d6 Acid damage.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Alchemist''s Fire', 'alchemists-fire', 'gear', 2500, 1, 'When you take the Attack action, you can replace one of your attacks with throwing a flask of Alchemist''s Fire. Target one creature or object you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 1d4 Fire damage and start burning (see “Rules Glossary”).', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Alchemist''s Supplies', 'alchemists-supplies', 'tool', 5000, 8, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Amulet', 'amulet', 'focus', 500, 1, 'A Holy Symbol takes one of the forms in the Holy Symbol table and is bejeweled or painted to channel divine magic. A Cleric or Paladin can use a Holy Symbol as a Spellcasting Focus.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Antitoxin', 'antitoxin', 'gear', 5000, 1, 'As a Bonus Action, you can drink a vial of Antitoxin to gain Advantage on saving throws to avoid or end the Poisoned condition for 1 hour.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Arrows', 'arrows', 'ammunition', 100, 1, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Backpack', 'backpack', 'gear', 200, 5, 'A Backpack holds up to 30 pounds within 1 cubic foot. It can also serve as a saddlebag.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Bagpipes', 'bagpipes', 'tool', 3000, 6, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Ball bearings', 'ball-bearings', 'gear', 100, 2, 'As a Utilize action, you can spill Ball Bearings from their pouch. They spread to cover a level, 10-footsquare area within 10 feet of yourself. A creature that enters this area for the first time on a turn must succeed on a DC 10 Dexterity saving throw or have the Prone condition. It takes 10 minutes to recover the Ball Bearings.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Barrel', 'barrel', 'gear', 200, 70, 'A Barrel holds up to 40 gallons of liquid or up to 4 cubic feet of dry goods.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Basket', 'basket', 'gear', 200, 2, 'A Basket holds up to 40 pounds within 2 cubic feet.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Battleaxe', 'battleaxe', 'weapon', 1000, 4, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Bedroll', 'bedroll', 'gear', 200, 25, 'A Bedroll sleeps one Small or Medium creature. While in a Bedroll, you automatically succeed on saving throws against extreme cold (see “Gameplay Toolbox”).', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Bell', 'bell', 'gear', 100, 1, 'When rung as a Utilize action, a Bell produces a sound that can be heard up to 60 feet away.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Blanket', 'blanket', 'gear', 500, 3, 'While wrapped in a blanket, you have Advantage on saving throws against extreme cold (see “Gameplay Toolbox”).', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Block and tackle', 'block-and-tackle', 'gear', 100, 5, 'A Block and Tackle allows you to hoist up to four times the weight you can normally lift.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Blowgun', 'blowgun', 'weapon', 1000, 1, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Book', 'book', 'gear', 2500, 5, 'A Book contains fiction or nonfiction. If you consult an accurate nonfiction Book about its topic, you gain a +5 bonus to Intelligence (Arcana, History, Nature, or Religion) checks you make about that topic.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
