INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Case, Crossbow Bolt', 'case-crossbow-bolt', 'gear', 100, 1, 'A Crossbow Bolt Case holds up to 20 Bolts.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Case, Map or Scroll', 'case-map-or-scroll', 'gear', 100, 1, 'A Map or Scroll Case holds up to 10 sheets of paper or 5 sheets of parchment.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Chain', 'chain', 'gear', 500, 6, 'As a Utilize action, you can wrap a Chain around an unwilling creature within 5 feet of yourself that has the Grappled, Incapacitated, or Restrained condition if you succeed on a DC 13 Strength (Athletics) check. If the creature''s legs are bound, the creature has the Restrained condition until it escapes. Escaping the Chain requires the creature to make a successful DC 18 Dexterity (Acrobatics) check as an action. Bursting the Chain requires a successful DC 20 Strength (Athletics) check as an action.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Chain Mail', 'chain-mail', 'armor', 7500, 55, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Chain Shirt', 'chain-shirt', 'armor', 5000, 14, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Chest', 'chest', 'gear', 5000, 20, 'A Chest holds up to 12 cubic feet of contents.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Climber''s Kit', 'climbers-kit', 'gear', 2500, 8, 'A Climber''s Kit includes boot tips, gloves, pitons, and a harness. As a Utilize action, you can use the Climber''s Kit to anchor yourself; when you do, you can''t fall more than 25 feet from the anchor point, and you can''t move more than 25 feet from there without undoing the anchor as a Bonus Action.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Clothes, Fine', 'clothes-fine', 'gear', 1500, 3, 'Fine Clothes are made of expensive fabrics and adorned with expertly crafted details. Some events and locations admit only people wearing these clothes.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Clothes, Traveler''s', 'clothes-travelers', 'gear', 500, 4, 'Traveler''s Clothes are resilient garments designed for travel in various environments.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
