INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Grappling Hook', 'grappling-hook', 'gear', 200, 4, 'As a Utilize action, you can throw the Grappling Hook at a railing, a ledge, or another catch within 50 feet of yourself, and the hook catches on if you succeed on a DC 13 Dexterity (Acrobatics) check. If you tied a Rope to the hook, you can then climb it.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
