INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Healer''s Kit', 'healers-kit', 'gear', 500, 3, 'A Healer''s Kit has ten uses. As a Utilize action, you can expend one of its uses to stabilize an Unconscious creature that has 0 Hit Points without needing to make a Wisdom (Medicine) check.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
