INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Ladder', 'ladder', 'gear', 10, 25, 'A Ladder is 10 feet tall. You must climb to move up or down it. Lamp (5 SP)', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
