INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Lock', 'lock', 'gear', 1000, 1, 'A Lock comes with a key. Without the key, a creature can use Thieves'' Tools to pick this Lock with a successful DC 15 Dexterity (Sleight of Hand) check.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
