INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Magnifying Glass', 'magnifying-glass', 'gear', 10000, 0, 'A Magnifying Glass grants Advantage on any ability check made to appraise or inspect a highly detailed item. Lighting a fire with a Magnifying Glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Manacles', 'manacles', 'gear', 200, 6, 'As a Utilize action, you can use Manacles to bind an unwilling Small or Medium creature within 5 feet of yourself that has the Grappled, Incapacitated, or Restrained condition if you succeed on a DC 13 Dexterity (Sleight of Hand) check. While bound, a creature has Disadvantage on attack rolls, and the creature is Restrained if the Manacles are attached to a chain or hook that is fixed in place. Escaping the Manacles requires a successful DC 20 Dexterity (Sleight of Hand) check as an action. Bursting them requires a successful DC 25 Strength (Athletics) check as an action.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Mason''s Tools', 'masons-tools', 'tool', 1000, 8, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Map', 'map', 'gear', 100, 0, 'If you consult an accurate Map, you gain a +5 bonus to Wisdom (Survival) checks you make to find your way in the place represented on it.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Mirror', 'mirror', 'gear', 500, 0.5, 'A handheld steel Mirror is useful for personal cosmetics but also for peeking around corners and reflecting light as a signal.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
