INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Net', 'net', 'gear', 100, 3, 'When you take the Attack action, you can replace one of your attacks with throwing a Net. Target a creature you can see within 15 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or have the Restrained condition until it escapes. The target succeeds automatically if it is Huge or larger.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Oil', 'oil', 'gear', 10, 1, 'You can douse a creature, object, or space with Oil or use it as fuel, as detailed below.
