INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Paper', 'paper', 'gear', 20, 0, 'One sheet of Paper can hold about 250 handwritten words.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Parchment', 'parchment', 'gear', 300, 0, 'One sheet of Parchment can hold about 250 handwritten words.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Perfume', 'perfume', 'gear', 500, 0, 'Perfume comes in a 4-ounce vial. For 1 hour after applying Perfume to yourself, you have Advantage on Charisma (Persuasion) checks made to influence an Indifferent Humanoid within 5 feet of yourself.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
