INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Plate Armor', 'plate-armor', 'armor', 150000, 65, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Playing Cards', 'playing-cards', 'tool', 50, 0, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Poison, Basic', 'poison-basic', 'gear', 10000, 0, 'As a Bonus Action, you can use a vial of Basic Poison to coat one weapon or up to three pieces of ammunition. A creature that takes Piercing or Slashing damage from the poisoned weapon or ammunition takes an extra 1d4 Poison damage. Once applied, the poison retains potency for 1 minute or until its damage is dealt, whichever comes first.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Pole', 'pole', 'gear', 5, 7, 'A Pole is 10 feet long. You can use it to touch something up to 10 feet away. If you must make a Strength (Athletics) check as part of a High or Long Jump, you can use the Pole to vault, giving yourself Advantage on the check.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Pot, Iron', 'pot-iron', 'gear', 200, 10, 'An Iron Pot holds up to 1 gallon.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Potion of Healing', 'potion-of-healing', 'gear', 5000, 0.5, 'This potion is a magic item. As a Bonus Action, you can drink it or administer it to another creature within 5 feet of yourself. The creature that drinks the magical red fluid in this vial regains 2d4 + 2 Hit Points.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Potter''s Tools', 'potters-tools', 'tool', 1000, 3, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Pouch', 'pouch', 'gear', 50, 1, 'A Pouch holds up to 6 pounds within one-fifth of a cubic foot.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Priest''s Pack', 'priests-pack', 'pack', 3300, 29, 'A Priest''s Pack contains the following items: Backpack, Blanket, Holy Water, Lamp, 7 days of Rations, Robe, and Tinderbox.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Quarterstaff', 'quarterstaff', 'weapon', 20, 4, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Quiver', 'quiver', 'gear', 100, 1, 'A Quiver holds up to 20 Arrows.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Ram, Portable', 'ram-portable', 'gear', 400, 35, 'You can use a Portable Ram to break down doors. When doing so, you gain a +4 bonus to the Strength check. One other character can help you use the ram, giving you Advantage on this check.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Rapier', 'rapier', 'weapon', 2500, 2, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Rations', 'rations', 'gear', 50, 2, 'Rations consist of travel-ready food, including jerky, dried fruit, hardtack, and nuts. See "Malnutrition" in "Rules Glossary" for the risks of not eating.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Reliquary', 'reliquary', 'focus', 500, 2, 'A Holy Symbol takes one of the forms in the Holy Symbol table and is bejeweled or painted to channel divine magic. A Cleric or Paladin can use a Holy Symbol as a Spellcasting Focus.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Ring Mail', 'ring-mail', 'armor', 3000, 40, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Robe', 'robe', 'gear', 100, 1, 'A Robe has vocational or ceremonial significance. Some events and locations admit only people wearing a Robe bearing certain colors or symbols.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Rod', 'rod', 'focus', 1000, 2, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Rope', 'rope', 'gear', 100, 5, 'As a Utilize action, you can tie a knot with Rope if you succeed on a DC 10 Dexterity (Sleight of Hand) check. The Rope can be burst with a successful DC 20 Strength (Athletics) check.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Sack', 'sack', 'gear', 1, 1, 'A Sack holds up to 30 pounds within 1 cubic foot.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
