INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Scholar''s Pack', 'scholars-pack', 'pack', 4000, 22, 'A Scholar''s Pack contains the following items: Backpack, Blanket, Book, Ink, Ink Pen, Lamp, 10 flasks of Oil, 10 sheets of Parchment, and Tinderbox.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
