INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Spellbook', 'spellbook', 'gear', 5000, 3, 'Essential for wizards, a spellbook is a leather-bound tome with 100 blank vellum pages suitable for recording spells.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Spell Scroll, Cantrip', 'spell-scroll-cantrip', 'gear', 3000, 0, 'A *Spell Scroll* (Cantrip) or *Spell Scroll* (Level 1) is a magic item that bears the words of a cantrip or level 1 spell, respectively, determined by the scroll''s creator. If the spell is on your class''s spell list, you can read the scroll and cast the spell using its normal casting time and without providing any Material components.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Spell Scroll, Level 1', 'spell-scroll-level-1', 'gear', 5000, 0, 'A *Spell Scroll* (Cantrip) or *Spell Scroll* (Level 1) is a magic item that bears the words of a cantrip or level 1 spell, respectively, determined by the scroll''s creator. If the spell is on your class''s spell list, you can read the scroll and cast the spell using its normal casting time and without providing any Material components.
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Spikes, Iron', 'spikes-iron', 'gear', 100, 2, 'Iron Spikes come in bundles of ten. As a Utilize action, you can use a blunt object, such as a Light Hammer, to hammer a spike into wood, earth, or a similar material. You can do so to jam a door shut or to then tie a Rope or Chain to the Spike.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Splint Armor', 'splint-armor', 'armor', 20000, 60, NULL, (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
