INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Spyglass', 'spyglass', 'gear', 100000, 1, 'Objects viewed through a Spyglass are magnified to twice their size.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
