INSERT INTO Equipment (equipmentName, equipmentSlug, equipmentKind, costCp, weightLb, equipmentDescription, sourceID) VALUES ('Waterskin', 'waterskin', 'gear', 20, 5, 'A Waterskin holds up to 4 pints. If you don''t drink sufficient water, you risk dehydration (see “Rules Glossary”).', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
